CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,email_verified_at TIMESTAMPTZ,status TEXT NOT NULL DEFAULT 'active',age_14_plus_confirmed_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS user_profiles (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,nickname TEXT NOT NULL UNIQUE,major TEXT NOT NULL,major_status TEXT NOT NULL,signup_source TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS user_consents (id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,terms_id TEXT NOT NULL,terms_version TEXT NOT NULL,required BOOLEAN NOT NULL,agreed BOOLEAN NOT NULL,agreed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS email_verifications (id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash TEXT NOT NULL,expires_at TIMESTAMPTZ NOT NULL,used_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS auth_sessions (id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,expires_at TIMESTAMPTZ NOT NULL,keep_signed_in BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
